use std::fs;
use std::path::{Path, PathBuf};

fn main() {
    let manifest_dir = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let vendor = manifest_dir.join("../../vendor/apollo");
    let modules_root = manifest_dir.join("../../modules");
    println!("cargo:rerun-if-changed={}", vendor.display());
    println!("cargo:rerun-if-changed={}", modules_root.display());

    let mut out = String::from(
        "// @generated by mul-apollo build.rs — do not edit\n\
         pub static LEGACY_MODULE_SOURCES: &[(&str, &str)] = &[\n",
    );
    let mut names: Vec<String> = fs::read_dir(&vendor)
        .map(|rd| {
            rd.filter_map(|e| e.ok())
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .filter(|n| n.ends_with(".txt"))
                .collect()
        })
        .unwrap_or_default();
    names.sort();
    for name in &names {
        let abs = vendor.join(name);
        let abs = abs.canonicalize().unwrap_or(abs);
        let abs_str = abs.to_string_lossy().replace('\\', "/");
        out.push_str(&format!(
            "    (\"{name}\", include_str!(r\"{abs_str}\")),\n"
        ));
    }
    out.push_str("];\n\n");

    out.push_str("pub static TOML_MODULE_SOURCES: &[(&str, &str)] = &[\n");
    let mut toml_files: Vec<PathBuf> = Vec::new();
    collect_tomls(&modules_root, &mut toml_files);
    toml_files.sort();
    for path in &toml_files {
        let name = path
            .strip_prefix(&modules_root)
            .unwrap_or(path)
            .to_string_lossy()
            .replace('\\', "/");
        let abs = path.canonicalize().unwrap_or_else(|_| path.clone());
        let abs_str = abs.to_string_lossy().replace('\\', "/");
        out.push_str(&format!(
            "    (\"{name}\", include_str!(r\"{abs_str}\")),\n"
        ));
    }
    out.push_str("];\n");

    let dest = Path::new(&std::env::var("OUT_DIR").unwrap()).join("legacy_modules.rs");
    fs::write(dest, out).unwrap();
}

fn collect_tomls(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(rd) = fs::read_dir(dir) else {
        return;
    };
    for entry in rd.filter_map(|e| e.ok()) {
        let path = entry.path();
        if path.is_dir() {
            collect_tomls(&path, out);
        } else if path.extension().and_then(|e| e.to_str()) == Some("toml") {
            out.push(path);
        }
    }
}
